and (TEMPLATE_ID like concat(concat('%', #{search,jdbcType=VARCHAR}), '%') or TEMPLATE_NAME like concat(concat('%', #{search,jdbcType=VARCHAR}), '%'))
and TEMPLATE_ID = #{initValue}
and PROFIT_TYPE = #{profitType}
and PROFIT_TYPE in
#{item}

