AND DEAL_MODE = #{dealMode,jdbcType=VARCHAR}
AND PROFIT_TYPE = #{profitType,jdbcType=VARCHAR}
and (TEMPLATE_ID in
null) or TEMPLATE_ID in (
#{item} )

select FIN_PRODUCT.FINPROD_ID finprodId, FIN_PRODUCT.FINPROD_ID templetId, FIN_PRODUCT.FINPROD_NAME templetName, FIN_PRODUCT_ADD.DEAL_MODE dealMode, FIN_PRODUCT.PROFIT_TYPE profitType, FIN_PRODUCT.OPERATION_TYPE operationType, FIN_PRODUCT_ADD.CLOSE_DAYS closedPeriod,
FIN_RATE_INFO.INT_TYPE rateType, FIN_PRODUCT_ADD.IS_CYCLE isCycle, FIN_PRODUCT_ADD.IS_LAY isLay, FIN_PRODUCT_ADD.LAY_TYPE layType, FIN_PRODUCT_ADD.PROFIT_FLAG prodProfitFlag, FIN_PRODUCT.ENTRUST_TYPE issueMode, FIN_PRODUCT.ENTRUSTER branchBank, FIN_PRODUCT.CALENDAR_ID calendarId, FIN_RATE_INFO.BASIS basis, FIN_PRODUCT.CCY ccy, FIN_PRODUCT_ADD.PUR_SPEED purRedDate, FIN_PRODUCT.ISSUE_TYPE issueType, FIN_PRODUCT_ADD.INVEST_NATURE investType, FIN_PRODUCT_ADD.SALE_MODE saleMode from FIN_PRODUCT left join FIN_PRODUCT_ADD on FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID
left join FIN_CASH_INFO on FIN_PRODUCT.FINPROD_ID = FIN_CASH_INFO.FINPROD_ID and FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1} and FIN_CASH_INFO.CASH_TYPE_2 = #{cashType2} left join FIN_RATE_INFO on FIN_RATE_INFO.CASH_ID = FIN_CASH_INFO.CASH_ID AND FIN_RATE_INFO.FINPROD_TYPE2 = FIN_PRODUCT.FINPROD_TYPE2 where FIN_PRODUCT.FINPROD_TYPE2 = #{finprodType2}
and FIN_PRODUCT.FINPROD_ID = #{finprodId}

select FIN_PRODUCT.FINPROD_ID finprodId, FIN_PRODUCT.FINPROD_ID templetId, FIN_PRODUCT.FINPROD_NAME templetName, FIN_PRODUCT_ADD.DEAL_MODE dealMode, FIN_PRODUCT.PROFIT_TYPE profitType, FIN_PRODUCT.OPERATION_TYPE operationType, FIN_PRODUCT_ADD.CLOSE_DAYS closedPeriod,
FIN_RATE_INFO.INT_TYPE rateType, FIN_PRODUCT_ADD.IS_CYCLE isCycle, FIN_PRODUCT_ADD.IS_LAY isLay, FIN_PRODUCT_ADD.LAY_TYPE layType, FIN_PRODUCT_ADD.PROFIT_FLAG prodProfitFlag, FIN_PRODUCT.ENTRUST_TYPE issueMode, FIN_PRODUCT.ENTRUSTER branchBank, FIN_PRODUCT.CALENDAR_ID calendarId, FIN_CASH_CALC_RULE.BASIS basis, FIN_PRODUCT.CCY ccy, FIN_PRODUCT_ADD.PUR_SPEED purRedDate, FIN_PRODUCT.ISSUE_TYPE issueType, FIN_PRODUCT_ADD.INVEST_NATURE investType, FIN_PRODUCT_ADD.SALE_MODE saleMode from FIN_PRODUCT left join FIN_PRODUCT_ADD on FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID
left join FIN_CASH_INFO on FIN_PRODUCT.FINPROD_ID = FIN_CASH_INFO.FINPROD_ID and FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1} and FIN_CASH_INFO.CASH_TYPE_2 = #{cashType2} left join FIN_CASH_CALC_RULE on FIN_CASH_INFO.CASH_ID = FIN_CASH_CALC_RULE.CASH_ID and FIN_CASH_CALC_RULE.EFF_DATE = FIN_PRODUCT.VDATE left join FIN_RATE_INFO on FIN_RATE_INFO.CASH_ID = FIN_CASH_INFO.CASH_ID AND FIN_RATE_INFO.FINPROD_TYPE2 = FIN_PRODUCT.FINPROD_TYPE2 where FIN_PRODUCT.FINPROD_TYPE2 = #{finprodType2}
and FIN_PRODUCT.FINPROD_NAME = #{finprodName}
and FIN_PRODUCT.FINPROD_ID != #{finprodId}
